import { EOF, SEP, parseGrammar, ruleText, symbolList, type Problem } from './grammar'
import type { ProjectData, Relation } from './project'

type Prec = ProjectData['prec']
export type Rel = Relation | ''

export const REL_CYCLE: Rel[] = ['', '<', '=', '>']
export const cellKey = (a: string, b: string) => a + SEP + b
export const precCols = (terminals: string[]) => [...terminals.filter((t) => t !== EOF), EOF]
export const getRel = (cells: Prec['cells'], a: string, b: string): Rel => cells[cellKey(a, b)] ?? ''

export function withRel(cells: Prec['cells'], a: string, b: string, value: Rel) {
  const next = { ...cells }
  if (value) next[cellKey(a, b)] = value
  else delete next[cellKey(a, b)]
  return next
}

// Drops cells that refer to terminals no longer in the table.
export function pruneCells(cells: Prec['cells'], terminals: string[]) {
  const keep = new Set(precCols(terminals))
  return Object.fromEntries(
    Object.entries(cells).filter(([k]) => {
      const [a, b] = k.split(SEP)
      return keep.has(a) && keep.has(b)
    }),
  )
}

export function precProblems(prec: Prec): Problem[] {
  const probs: Problem[] = []
  const cols = precCols(prec.terminals)
  const g = parseGrammar(prec.rules)
  g.errors.forEach((text) => probs.push({ level: 'bad', text }))
  const lhsSet = new Set(g.rules.map((r) => r.lhs))
  const byRhs = new Map<string, number>()
  g.rules.forEach((r, i) => {
    if (!r.rhs.length) probs.push({ level: 'bad', text: `Pravidlo ${i + 1} je ε-pravidlo – precedenčná SA ich nepovoľuje` })
    const k = r.rhs.join(SEP)
    if (byRhs.has(k)) {
      probs.push({ level: 'bad', text: `Pravidlá ${byRhs.get(k)} a ${i + 1} majú rovnakú pravú stranu (${r.rhs.join(' ')})` })
    } else byRhs.set(k, i + 1)
    r.rhs.forEach((s) => {
      if (!lhsSet.has(s) && !cols.includes(s)) probs.push({ level: 'warn', text: `Terminál ${s} z pravidla ${i + 1} nie je v tabuľke` })
    })
  })
  const filled = Object.keys(pruneCells(prec.cells, prec.terminals)).length
  if (!prec.terminals.length) probs.push({ level: 'info', text: 'Zadaj terminály alebo použi generátor.' })
  else {
    probs.push({
      level: 'info',
      text: `${cols.length}×${cols.length} tabuľka, vyplnených ${filled} buniek, prázdnych (= chyba) ${cols.length * cols.length - filled}`,
    })
  }
  if (prec.terminals.length && !g.rules.length) probs.push({ level: 'info', text: 'Bez redukčných pravidiel sa nedá simulovať.' })
  return probs
}

export interface StackItem {
  kind: 't' | 'n' | 'm'
  s: string
}

export interface PrecTraceRow {
  stack: StackItem[]
  op: Rel
  input: string
  rule: string
}

export function simulatePrec(prec: Prec) {
  const toks = symbolList(prec.input)
  const g = parseGrammar(prec.rules)
  if (!toks.length || !g.rules.length) return null
  const start = g.rules[0].lhs
  const byRhs = new Map<string, { lhs: string; rhs: string[]; n: number }>()
  g.rules.forEach((r, i) => {
    const k = r.rhs.join(SEP)
    if (!byRhs.has(k)) byRhs.set(k, { ...r, n: i + 1 })
  })
  const input = [...toks, EOF]
  const stack: StackItem[] = [{ kind: 't', s: EOF }]
  const rows: PrecTraceRow[] = []
  const output: number[] = []
  let pos = 0
  let result: { ok: boolean; message: string } | null = null
  for (let step = 0; step < 5000 && !result; step++) {
    let ti = stack.length - 1
    while (stack[ti].kind !== 't') ti--
    const a = stack[ti].s
    const b = input[pos]
    const row: PrecTraceRow = { stack: [...stack], op: '', input: input.slice(pos).join(' '), rule: '' }
    rows.push(row)
    if (b === EOF && stack.length === 2 && stack[1].kind === 'n' && stack[1].s === start) {
      // Slide 7 lists the rules in the order the reductions happened.
      result = { ok: true, message: `Úspech. Pravý rozbor: ${output.join(' ')}` }
      break
    }
    const rel = getRel(prec.cells, a, b)
    row.op = rel
    if (rel === '=') {
      stack.push({ kind: 't', s: b })
      pos++
    } else if (rel === '<') {
      stack.splice(ti + 1, 0, { kind: 'm', s: '<' })
      stack.push({ kind: 't', s: b })
      pos++
    } else if (rel === '>') {
      let mi = stack.length - 1
      while (mi >= 0 && stack[mi].kind !== 'm') mi--
      if (mi < 0) {
        result = { ok: false, message: 'Na zásobníku chýba <' }
        break
      }
      const y = stack.slice(mi + 1).map((it) => it.s)
      const r = byRhs.get(y.join(SEP))
      if (!r) {
        result = { ok: false, message: `Žiadne pravidlo s pravou stranou „${y.join(' ')}“` }
        break
      }
      stack.splice(mi, stack.length - mi, { kind: 'n', s: r.lhs })
      output.push(r.n)
      row.rule = `${r.n}: ${ruleText(r)}`
    } else {
      result = { ok: false, message: `Prázdna bunka [${a}, ${b}]` }
    }
  }
  return { rows, ...(result ?? { ok: false, message: 'Príliš veľa krokov' }) }
}
